class ChatStreamSession:
    """Replays a quest log JSONL file then streams live events from a bus."""

    def __init__(self, log_path: Path, ws, event_bus: ChatEventBus) -> None:
        self._log_path = log_path
        self._ws = ws
        self._event_bus = event_bus

    def run(self) -> None:
        subscription = self._event_bus.subscribe(self._log_path)
        try:
            mapper = QuestLogToAguiMapper()
            replay_high_water = self._replay_file(mapper)
            if replay_high_water is None:
                return
            self._live_loop(mapper, subscription, replay_high_water)
        finally:
            subscription.unsubscribe()

    def _send(self, message: dict) -> bool:
        try:
            self._ws.send(json.dumps(message))
            return True
        except Exception:
            return False

    def _send_events(self, events: list[dict]) -> bool:
        if not events:
            return True
        return self._send({"type": "events", "events": events})

    def _replay_file(self, mapper: QuestLogToAguiMapper) -> int | None:
        replay_high_water = 0

export class ChatViewProvider implements vscode.WebviewViewProvider
{


  resolveWebviewView(webviewView: vscode.WebviewView): void | Thenable<void>
  {
    this.m_webviewView = webviewView;
    webviewView.webview.options = {
      enableScripts: true,
      localResourceRoots: [vscode.Uri.joinPath(this.m_extensionUri, "out", "webview")],
    };

    const nonce = randomBytes(16).toString("base64");
    webviewView.webview.html = BuildChatHtml(webviewView.webview, this.m_extensionUri, nonce);

    webviewView.webview.onDidReceiveMessage((message: { type?: string; id?: string }) =>
    {
      if (message.type !== "command")
      {
        return;
      }

      if (message.id === "toggleSession")
      {
        void vscode.commands.executeCommand(CMD_TOGGLE_SESSION);
        return;
      }

      if (message.id === "commitAndRespond")
      {
        void vscode.commands.executeCommand(CMD_COMMIT_AND_RESPOND);
      }
    });

    const unsubModel = this.m_chatModel.subscribe(() =>
    {
      this.SchedulePostSnapshot();
    });
    const unsubState = this.m_session.OnStateChanged(() =>
    {
      this.SchedulePostSnapshot();
    });

    webviewView.onDidDispose(() =>
    {
      unsubModel();
      unsubState.dispose();
      this.CancelPostSnapshot();
      this.m_webviewView = undefined;
    });

    this.SchedulePostSnapshot();
  }

  private CancelPostSnapshot(): void
