            String(s.step)
          )} — ${EscapeHtml(s.filename)}</option>`
      )
      .join("");
    const logBody = `<pre class="dash-pre dash-pre--raw">${EscapeHtml(log.jsonl_raw || "")}</pre>`;
    logPanel = `
      <div class="dash-agent-log-head">
