  color: var(--dash-muted);
  margin-bottom: 8px;
}

.dash-issue-title {
  margin: 0 0 8px;
  font-size: 16px;
  font-weight: 600;
}

.dash-issue-details {
  font-size: 13px;
}

.dash-issue-resolution {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--dash-border);
  font-size: 13px;
}

.dash-md-muted {
  margin-top: 6px;
  font-size: 13px;
  color: var(--dash-muted);
}

.dash-resp-summary {
  margin-top: 28px;
  padding-top: 20px;
  border-top: 1px solid var(--dash-border);
}

.dash-resp-summary ul {
  padding-left: 20px;
  margin: 8px 0 0;
}

.dash-resp-summary li {
  margin-bottom: 12px;
}

.dash-diff-layout {
  display: grid;
  grid-template-columns: minmax(200px, 280px) 1fr;
  gap: 16px;
  align-items: start;
}

@media (max-width: 900px) {
  .dash-diff-layout {
    grid-template-columns: 1fr;
  }
}

.dash-diff-aside {
  border: 1px solid var(--dash-border);
  border-radius: var(--dash-radius);
  background: var(--dash-surface);
  max-height: 70vh;
  overflow: auto;
}

.dash-diff-filenav ul {
  list-style: none;
  margin: 0;
  padding: 8px;
}

.dash-diff-filenav li {
  margin-bottom: 4px;
}

.dash-diff-file {
  width: 100%;
  text-align: left;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--dash-text);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.dash-diff-file:hover {
  background: var(--dash-elevated);
}

.dash-diff-file--active {
  border-color: var(--dash-accent);
  background: var(--dash-elevated);
}

.dash-diff-main {
  border: 1px solid var(--dash-border);
  border-radius: var(--dash-radius);
  background: var(--dash-bg);
  min-height: 200px;
  overflow: auto;
}

.dash-diff-binary {
  padding: 24px;
  font-size: 14px;
}

.dash-diff-grid {
  display: grid;
  grid-template-columns: minmax(2.5rem, auto) minmax(0, 1fr) minmax(2.5rem, auto) minmax(0, 1fr);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  line-height: 1.45;
}

.dash-diff-colhead {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 8px 10px;
  background: var(--dash-elevated);
  border-bottom: 1px solid var(--dash-border);
  font-weight: 700;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--dash-muted);
}

.dash-diff-head-old {
  grid-column: 1 / 3;
}

.dash-diff-head-new {
  grid-column: 3 / 5;
}

.dash-diff-row {
  display: contents;
}

.dash-diff-gutter {
  padding: 1px 6px;
  color: var(--dash-muted);
  background: var(--dash-surface);
  border-bottom: 1px solid var(--dash-border);
  text-align: right;
  user-select: none;
}

.dash-diff-cell {
  padding: 1px 8px;
  white-space: pre-wrap;
  word-break: break-word;
  border-bottom: 1px solid var(--dash-border);
  background: var(--dash-bg);
}

.dash-diff-cell--del {
  background: rgba(239, 68, 68, 0.12);
}

.dash-diff-cell--add {
  background: rgba(34, 197, 94, 0.12);
}

.dash-diff-hunk {
  grid-column: 1 / -1;
  padding: 6px 10px;
  background: #1e293b;
  color: #94a3b8;
  border-bottom: 1px solid var(--dash-border);
  white-space: pre-wrap;
}

.dash-diff-row--other .dash-diff-span4 {
  grid-column: 1 / -1;
  padding: 4px 10px;
  border-bottom: 1px solid var(--dash-border);
  color: var(--dash-muted);
}

.dash-agent-layout {
  display: grid;
  grid-template-columns: minmax(240px, 320px) 1fr;
  gap: 20px;
  align-items: start;
}

@media (max-width: 800px) {
  .dash-agent-layout {
    grid-template-columns: 1fr;
  }
}

.dash-agent-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.dash-agent-pill {
  width: 100%;
  text-align: left;
  padding: 10px 12px;
  margin-bottom: 8px;
  border-radius: var(--dash-radius);
  border: 1px solid var(--dash-border);
  background: var(--dash-surface);
  color: var(--dash-text);
  font: inherit;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.dash-agent-pill:hover {
  border-color: var(--dash-accent);
}

.dash-agent-pill--active {
  border-color: var(--dash-accent);
  box-shadow: 0 0 0 1px var(--dash-accent);
}

.dash-agent-scope {
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--dash-muted);
}

.dash-agent-meta,
.dash-agent-logref {
  font-size: 12px;
  color: var(--dash-muted);
}

.dash-agent-main {
  border: 1px solid var(--dash-border);
  border-radius: var(--dash-radius);
  padding: 16px 20px;
  background: var(--dash-surface);
  min-height: 120px;
}

.dash-agent-log-head .dash-field {
  max-width: 24rem;
}

