:root {
  --dash-bg: #0f1419;
  --dash-surface: #1a2332;
  --dash-elevated: #232f3e;
  --dash-border: #2d3a4d;
  --dash-text: #e6edf3;
  --dash-muted: #8b9cb3;
  --dash-accent: #3b82f6;
  --dash-accent-dim: #2563eb;
  --dash-warn: #f59e0b;
  --dash-danger: #ef4444;
  --dash-success: #22c55e;
  --dash-font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
    sans-serif;
  --dash-radius: 8px;
  --dash-gap: 12px;
  --dash-nav-width: 260px;
  --dash-page-nav-width: 200px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--dash-font);
  font-size: 14px;
  line-height: 1.45;
  color: var(--dash-text);
  background: var(--dash-bg);
}

.dash-root {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.dash-banner {
  background: var(--dash-warn);
  color: #111;
  padding: 10px 16px;
  font-weight: 600;
}

.dash-banner--error {
  background: var(--dash-danger);
  color: #fff;
}

.dash-banner--success {
  background: var(--dash-success);
  color: #06130a;
}

.dash-topbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--dash-gap);
  padding: 10px 16px;
  border-bottom: 1px solid var(--dash-border);
  background: var(--dash-surface);
}

.dash-topbar label {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--dash-muted);
  font-size: 13px;
}

.dash-topbar select {
  min-width: 220px;
  padding: 6px 10px;
  border-radius: 6px;
  border: 1px solid var(--dash-border);
  background: var(--dash-elevated);
  color: var(--dash-text);
}

.dash-btn {
  padding: 6px 14px;
  border-radius: 6px;
  border: 1px solid var(--dash-border);
  background: var(--dash-elevated);
  color: var(--dash-text);
  cursor: pointer;
  font: inherit;
}

.dash-btn:hover {
  border-color: var(--dash-accent);
  color: var(--dash-accent);
}

.dash-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.dash-btn--primary {
  background: var(--dash-accent);
  border-color: var(--dash-accent-dim);
  color: #fff;
  font-weight: 600;
}

.dash-btn--primary:hover:not(:disabled) {
  background: var(--dash-accent-dim);
  color: #fff;
}

.dash-run-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin: 12px 0 8px;
}

.dash-advance-hint {
  margin: 0 0 16px;
  font-size: 13px;
  color: var(--dash-muted);
}

.dash-run-error {
  color: var(--dash-danger);
  margin: 0 0 12px;
  font-size: 13px;
}

.dash-status {
  margin-left: auto;
  font-size: 12px;
  color: var(--dash-muted);
}

.dash-layout {
  flex: 1;
  display: grid;
  grid-template-columns: var(--dash-nav-width) var(--dash-page-nav-width) 1fr;
  min-height: 0;
}

@media (max-width: 960px) {
  .dash-layout {
    grid-template-columns: 1fr;
    grid-template-rows: auto auto 1fr;
