  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--dash-muted);
}

.dash-agent-meta,
.dash-agent-logref {
  font-size: 12px;
  color: var(--dash-muted);
}

.dash-agent-main {
  border: 1px solid var(--dash-border);
  border-radius: var(--dash-radius);
  padding: 16px 20px;
  background: var(--dash-surface);
  min-height: 120px;
}

.dash-agent-log-head .dash-field {
  max-width: 24rem;
}

