  if (sub === "physicalplan") {
    const files = pay.files || [];
    if (files.length === 0) {
      main.innerHTML = `${head}<p class="dash-empty">No markdown files under physicalplan/ for this slice.</p>`;
      return;
    }
    if (!state.contentCache.planViewMode) {
      state.contentCache.planViewMode = "rendered";
    }
