    const selName = state.contentCache.planSelectedFile || files[0].name;
    const file = files.find((f) => f.name === selName) || files[0];
    const opts = files
      .map(
        (f) =>
          `<option value="${EscapeHtml(f.name)}" ${f.name === file.name ? "selected" : ""}>${EscapeHtml(
