    <dl class="dash-kv">
      <dt>Quest state</dt><dd>${EscapeHtml(ov.quest_state)}</dd>
      <dt>Active slice</dt><dd>${ov.current_slice == null ? "—" : EscapeHtml(String(ov.current_slice))}</dd>
